import csv
import sqlite3
from collections import defaultdict

riverside_districts = set()
frpm_data = []
with open('csv/frpm.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        district = row['District Name']
        if district and 'riverside' in district.lower():
            riverside_districts.add(district)
            frpm_data.append({'school_name': row['School Name'], 'district_name': district, 'charter_funding_type': row.get('Charter Funding Type', ''), 'cdscode': row['CDSCode']})

conn = sqlite3.connect('db/satscores.db')
cursor = conn.cursor()
cursor.execute('SELECT cds, AVG(AvgScrMath) as avg_math FROM satscores GROUP BY cds')
cds_avg_math = {}
for row in cursor.fetchall():
    cds_avg_math[row[0]] = row[1]

district_schools = defaultdict(list)
for school in frpm_data:
    cds = school['cdscode']
    district = school['district_name']
    avg_math = cds_avg_math.get(cds, 0)
    if avg_math is not None:
        district_schools[district].append({'school_name': school['school_name'], 'funding_type': school['charter_funding_type'], 'avg_math': avg_math})

district_avg_math = {}
for district, schools in district_schools.items():
    math_scores = [s['avg_math'] for s in schools]
    if math_scores:
        district_avg_math[district] = sum(math_scores) / len(math_scores)

qualifying_districts = [d for d, avg in district_avg_math.items() if avg > 400]
print('Qualifying districts:', qualifying_districts)
results = []
for district in qualifying_districts:
    for school in district_schools[district]:
        results.append({'school_name': school['school_name'], 'funding_type': school['funding_type']})
print('Total schools:', len(results))
for r in results[:5]:
    print(r)
conn.close()

